def largestRectangleArea(heights):
    n = len(heights)
    best = 0
    for i in range(n):
        l = i
        while l > 0 and heights[l - 1] >= heights[i]:
            l -= 1
        r = i
        while r < n - 1 and heights[r + 1] >= heights[i]:
            r += 1
        best = max(best, heights[i] * (r - l + 1))
    return best
